Declare Function TLBuildCalendar PeopleCode TL_TIME_AET.PERIOD_ID FieldFormula;
REM **************************************************;
REM Call Function to build out calendar from period template
REM
REM As a function the routine supports both batch and online 
REM processing without process scheduler
REM **************************************************;
Local any &s;
Local Record &TL_TIME_AET;

&TL_TIME_AET = CreateRecord(Record.TL_TIME_AET);
&TL_TIME_AET.START_DT.Value = TL_TIME_AET.START_DT.Value;
&TL_TIME_AET.END_DT.Value = TL_TIME_AET.END_DT.Value;
&TL_TIME_AET.OVERRIDE_IND.Value = TL_TIME_AET.OVERRIDE_IND.Value;
&TL_TIME_AET.START_WEEK_DAY_IND.Value = TL_TIME_AET.START_WEEK_DAY_IND.Value;
&TL_TIME_AET.PERIOD_ID.Value = TL_TIME_AET.PERIOD_ID.Value;
&TL_TIME_AET.PERIOD_TYPE.Value = TL_TIME_AET.PERIOD_TYPE.Value;
&TL_TIME_AET.SUBTYPE_IND.Value = TL_TIME_AET.SUBTYPE_IND.Value;
&TL_TIME_AET.START_DAY_OF_WEEK.Value = TL_TIME_AET.START_DAY_OF_WEEK.Value;
&TL_TIME_AET.PERIOD_LENGTH.Value = TL_TIME_AET.PERIOD_LENGTH.Value;
&TL_TIME_AET.OFFSET_DAYS.Value = TL_TIME_AET.OFFSET_DAYS.Value;

TLBuildCalendar(&TL_TIME_AET);

rem Truncate timestamp to drop sub-seconds;
&s = %Time;
TL_TIME_AET.TIME_RECORDED.Value = Substring(&s, 1, 8);

